<div class="form-fields"><label>Ваше имя<input name="name" autocomplete="name" maxlength="100" required placeholder="Как к вам обращаться?"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" maxlength="22" pattern="\+?[0-9 \(\)\-]{10,22}" required placeholder="+7 (___) ___-__-__"></label><label>Город<input name="city" autocomplete="address-level2" required maxlength="100" placeholder="Например, Екатеринбург"></label><label>{{ $kind === 'order' ? 'Пожелания к заказу' : 'Расскажите о ваших планах' }}<textarea name="comment" maxlength="1000" rows="3" placeholder="Необязательно"></textarea></label></div>
<label class="honeypot" aria-hidden="true">Сайт<input name="website" tabindex="-1" autocomplete="off"></label>
<label class="consent"><input type="checkbox" name="consent" required> <span>Согласен на обработку имени, телефона и города для ответа на заявку. <button type="button" class="text-link" data-privacy-open>Подробнее</button></span></label>
